import { CommonModule } from '@angular/common';
import { Component, OnInit, inject, signal } from '@angular/core';
import { NotificationResponse } from '../../../core/models/models';
import { NotificationService } from '../../../core/services/notification.service';
@Component({selector:'app-notifications',standalone:true,imports:[CommonModule],template:`<div class="bg-paper"><div class="site-container page-shell max-w-[900px]"><header class="page-header"><div class="flex flex-wrap items-end justify-between gap-4"><div><p class="eyebrow">Tài khoản</p><h1 class="page-title">Thông báo</h1><p class="page-description">Cập nhật về đơn hàng, hệ thống và tài khoản.</p></div><button class="btn-secondary" (click)="markAll()">Đánh dấu tất cả đã đọc</button></div></header><div class="flex gap-2 overflow-auto border-b border-border pb-4"><button class="rounded-full px-4 py-2 text-sm font-medium transition-colors" [class.bg-secondary]="!type" [class.text-white]="!type" [class.bg-cream]="type!==''" (click)="type='';load()">Tất cả</button><button class="rounded-full px-4 py-2 text-sm font-medium transition-colors" [class.bg-secondary]="type==='don_hang'" [class.text-white]="type==='don_hang'" [class.bg-cream]="type!=='don_hang'" (click)="type='don_hang';load()">Đơn hàng</button><button class="rounded-full px-4 py-2 text-sm font-medium transition-colors" [class.bg-secondary]="type==='he_thong'" [class.text-white]="type==='he_thong'" [class.bg-cream]="type!=='he_thong'" (click)="type='he_thong';load()">Hệ thống</button></div>@if(loading()){<div class="skeleton mt-6 h-52 rounded-xl"></div>}@else{<div class="mt-4 divide-y divide-border overflow-hidden rounded-xl border border-border bg-surface">@for(n of items();track n.notificationId){<article class="p-5 transition-colors hover:bg-paper" [class.opacity-70]="n.status==='da_doc'"><div class="flex items-start justify-between gap-4"><div><div class="flex items-center gap-2"><h2 class="text-base font-semibold text-secondary">{{n.title}}</h2>@if(n.status==='chua_doc'){<span class="h-2.5 w-2.5 rounded-full bg-primary" aria-label="Chưa đọc"></span>}</div><p class="mt-2 text-sm leading-7 text-body">{{n.content}}</p><p class="mt-2 text-xs text-muted">{{n.createdAt|date:'dd/MM/yyyy HH:mm'}}</p></div><div class="flex shrink-0 gap-1"><button class="btn-ghost text-xs" (click)="toggle(n)">{{n.status==='chua_doc'?'Đánh dấu đã đọc':'Đánh dấu chưa đọc'}}</button><button class="btn-ghost text-xs" (click)="archive(n)">Lưu trữ</button></div></div></article>}@empty{<p class="py-14 text-center text-sm text-muted">Không có thông báo nào.</p>}</div>}</div></div>`})
export class NotificationsComponent implements OnInit{private api=inject(NotificationService);items=signal<NotificationResponse[]>([]);loading=signal(true);type='';ngOnInit(){this.load();}load(){this.loading.set(true);this.api.getNotifications({type:this.type||undefined}).subscribe({next:r=>{this.items.set(r.items);this.loading.set(false);},error:()=>this.loading.set(false)});}markAll(){this.api.markAllRead().subscribe(()=>this.load());}toggle(n:NotificationResponse){this.api.toggleRead(n.notificationId).subscribe(()=>this.load());}archive(n:NotificationResponse){this.api.archive(n.notificationId).subscribe(()=>this.load());}}